import{z as n,x as B,o as r,c as d,q as A,j as o,D as e,d as E,s,S as l,b as i}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"virtio","description":"","frontmatter":{"title":"virtio","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virtio.md","filePath":"cs/virtio.md","lastUpdated":1791413859000}'),p={name:"cs/virtio.md"};function c(h,a,m,D,v,f){const t=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="virtio" tabindex="-1">virtio <a class="header-anchor" href="#virtio" aria-label="Permalink to &quot;virtio&quot;">​</a></h1><div class="epigraph"><p>virtio 让客机驱动与宿主后端共享描述符环：客机踢队列，宿主处理真实 I/O，避免逐端口模拟传统设备。</p><footer>—— 据 Russell, virtio: Towards a De-Facto Standard For Virtual I/O Devices, 2008；virtio 规范的教学整理</footer></div><p><a href="/cs/ept-npt">上一课</a>加快了译址。<a href="/cs/trap-and-emulate">陷阱与模拟</a> 若对每个 <code>out</code> 到虚拟磁盘端口都陷入，块 I/O 会毁。<a href="/cs/bio-block">bio</a> 与 <a href="/cs/io-dma">DMA</a> 在宿主侧已能搬页。缺口是<strong>半虚拟化 I/O</strong>：客机知道自己在虚拟机里，使用约定好的环，而不是假装成一台古老的 IDE。操作系统课在此收束；下一课进入文件系统实现，从<a href="/cs/fat-filesystem">FAT 与目录项</a>读起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全模拟：客驱动以为有 PCI 网卡，每个寄存器访问陷入 VMM，再模拟。正确但慢。virtio：客机里的 virtio-blk/net 驱动把请求填进共享内存环（GPA 已由 EPT 落到宿主页），一次门铃通知宿主。宿主线程或 vhost 取出，走真 <a href="/cs/blk-mq">blk-mq</a> 或真网卡，完成时中断客机。缺口不是发明以太网帧格式——那是<a href="/cs/layering-e2e">分层与端到端</a>——而是这条队列契约。</p><p><span class="marginnote">直觉类比：共享描述符环像两个部门共用的传送带托盘——客机把托盘装好（描述符指向自己的缓冲），敲一下铃，宿主端取走办真事，办完把回执放上另一条传送带；全程不进对方房间，只共享托盘与铃。</span></p><p><span class="marginnote">现代 virtio 可用 virtiofs、vsock 等。本课以块与网为原型。规范由 OASIS virtio 维护；Russell 2008 是早期陈述。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发现：虚拟 PCI 设备表明 virtio ID。驱动协商特性，分配环。提交：描述符指向客缓冲（GPA）。宿主翻译成 HPA（EPT 或 IOMMU），执行 I/O。完成：写 used 环，注入中断。与容器的 veth 不同：这里有客内核驱动；容器直接用宿主系统调用。</p><p><span class="marginnote">数字实例：全模拟时代每个端口寄存器写入都陷入一次，一笔块 I/O 动辄几十次陷入；virtio 把一批请求攒进环里，一次门铃换一批——陷入次数从「按寄存器计」降到「按批次计」，这一两个数量级的差就是快的来源。</span></p>',10)),(r(),o(l,null,{default:e(()=>[s(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20GDRV%5B%22%E5%AE%A2%20virtio%20%E9%A9%B1%E5%8A%A8%22%5D%20--%3E%20RING%5B%22%E5%85%B1%E4%BA%AB%E6%8F%8F%E8%BF%B0%E7%AC%A6%E7%8E%AF%22%5D%0A%20%20RING%20--%3E%20BE%5B%22%E5%AE%BF%E4%B8%BB%E5%90%8E%E7%AB%AF%22%5D%0A%20%20BE%20--%3E%20REAL%5B%22%E7%9C%9F%E5%9D%97%E8%AE%BE%E5%A4%87%E6%88%96%E7%BD%91%E5%8D%A1%22%5D%0A%20%20REAL%20--%3E%20IRQ%5B%22%E5%AE%8C%E6%88%90%E4%B8%AD%E6%96%AD%E5%AE%A2%E6%9C%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[E("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,[E("virtio 把 I/O 虚拟化从「指令级模拟」改成「批量共享内存协议」，与 io_uring 的精神相近，对象是客/宿而不是用户/核。它依赖 EPT 让环所在页共享，依赖中断注入让客机调度它的驱动。操作系统课的设备模型到此能接到真实吞吐。跨机器的命名与可靠性不在 virtio 里——"),i("a",{href:"/cs/layering-e2e"},"分层与端到端"),E(" 从「两台主机」重新提问。")],-1)),(r(),o(l,null,{default:e(()=>[s(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILL%5B%22%E5%AE%A2%E9%A9%B1%E5%8A%A8%E6%8A%8A%E8%AF%B7%E6%B1%82%E5%A1%AB%E5%85%A5%20avail%20%E7%8E%AF%22%5D%20--%3E%20KICK%5B%22%E5%86%99%E9%97%A8%E9%93%83%E9%80%9A%E7%9F%A5%E5%AE%BF%E4%B8%BB%22%5D%0A%20%20KICK%20--%3E%20TAKE%5B%22%E5%AE%BF%E4%B8%BB%E5%90%8E%E7%AB%AF%E4%BB%8E%E7%8E%AF%E5%8F%96%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20TAKE%20--%3E%20GPA%5B%22%E6%8C%89%20GPA%20%E7%BB%8F%20EPT%20%E6%89%BE%E5%88%B0%E5%AE%BF%E4%B8%BB%E9%A1%B5%22%5D%0A%20%20GPA%20--%3E%20EXEC%5B%22%E6%89%A7%E8%A1%8C%E7%9C%9F%E5%AE%9E%E5%9D%97%E8%AE%BE%E5%A4%87%E6%88%96%E7%BD%91%E5%8D%A1%20I%2FO%22%5D%0A%20%20EXEC%20--%3E%20USED%5B%22%E5%86%99%20used%20%E7%8E%AF%E6%A0%87%E8%AE%B0%E5%AE%8C%E6%88%90%22%5D%0A%20%20USED%20--%3E%20IRQ%5B%22%E6%B3%A8%E5%85%A5%E4%B8%AD%E6%96%AD%E5%94%A4%E9%86%92%E5%AE%A2%E6%9C%BA%22%5D%0A%20%20IRQ%20--%3E%20REAP%5B%22%E5%AE%A2%E9%A9%B1%E5%8A%A8%E4%BB%8E%E7%8E%AF%E9%87%8C%E6%94%B6%E5%89%B2%E7%BB%93%E6%9E%9C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">特性协商可翻译成「先对暗号再干活」：驱动报出自己会什么（间接描述符、事件索引等），后端回一个交集，双方只按交集工作——客机新旧系统与宿主新旧后端因此可以混搭，谁也不必等谁一起升级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SR-IOV 的全部 VF 配置。不把每代 virtio 规范章节当考纲。操作系统主干到此结束，再往后的课不再添 OS 对象；网络课假定一台机器已能做 DMA 与队列。</p><p>后课默认：客机 I/O 可经半虚拟化队列到达宿主设备。两台机器之间如何分层与端到端查错，后面的<a href="/cs/layering-e2e">分层与端到端</a>一课会展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>virtio 用共享环做半虚拟化 I/O，减少寄存器陷入。</li><li>宿主后端接已有块层与 DMA；客机仍是完整内核。</li><li>跨主机协议分层是后面<a href="/cs/layering-e2e">分层与端到端</a>一课的内容。</li><li>出处：Russell, 2008；OASIS virtio；Tanenbaum <em>MOS</em>。</li></ul>',6))])}const F=n(p,[["render",c]]);export{I as __pageData,F as default};
